using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be 3–100 characters.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = "";

    [Required(ErrorMessage = "Ingredients are required.")]
    [MinLength(10, ErrorMessage = "Please provide at least 10 characters of ingredients.")]
    public string Ingredients { get; set; } = "";

    [Required(ErrorMessage = "Steps are required.")]
    [MinLength(10, ErrorMessage = "Please provide at least 10 characters of instructions.")]
    public string Steps { get; set; } = "";
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public static readonly string[] Categories =
        ["Breakfast", "Lunch", "Dinner", "Desserts", "Snacks", "Beverages"];

    public RecipeService()
    {
        _recipes =
        [
            new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1½ cups milk\n2 tbsp sugar\n1 tsp baking powder\n¼ tsp salt\n2 tbsp melted butter",
                Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs, milk, and melted butter together.\n3. Combine wet and dry ingredients until just blended.\n4. Heat a lightly oiled griddle over medium-high heat.\n5. Pour batter onto griddle and cook until bubbles form, then flip.\n6. Serve with maple syrup and fresh berries.",
                TotalRatingPoints = 18, RatingCount = 4 },
            new() { Id = 2, Title = "Grilled Chicken Salad", Category = "Lunch",
                Ingredients = "2 chicken breasts\n4 cups mixed greens\n1 cup cherry tomatoes\n½ cucumber\n¼ red onion\nOlive oil and lemon dressing",
                Steps = "1. Season chicken with salt, pepper, and olive oil.\n2. Grill chicken for 6–7 minutes per side until cooked through.\n3. Slice chicken and let rest.\n4. Toss greens, tomatoes, cucumber, and onion in a bowl.\n5. Top with sliced chicken and drizzle with dressing.",
                TotalRatingPoints = 14, RatingCount = 3 },
            new() { Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Ingredients = "400g spaghetti\n500g ground beef\n1 onion, diced\n2 garlic cloves\n400g crushed tomatoes\n2 tbsp tomato paste\nFresh basil\nParmesan cheese",
                Steps = "1. Cook spaghetti according to package directions.\n2. Brown ground beef in a large pan, then drain excess fat.\n3. Add onion and garlic, sauté until soft.\n4. Stir in crushed tomatoes and tomato paste.\n5. Simmer for 20 minutes.\n6. Serve sauce over spaghetti with fresh basil and Parmesan.",
                TotalRatingPoints = 24, RatingCount = 5 },
            new() { Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "200g dark chocolate\n150g butter\n3 eggs\n3 egg yolks\n75g sugar\n50g flour\nButter and cocoa for ramekins",
                Steps = "1. Preheat oven to 220°C (425°F).\n2. Melt chocolate and butter together.\n3. Whisk eggs, yolks, and sugar until thick.\n4. Fold chocolate mixture into eggs, then fold in flour.\n5. Pour into buttered, cocoa-dusted ramekins.\n6. Bake 12–14 minutes until edges are set but center jiggles.\n7. Invert onto plates and serve immediately.",
                TotalRatingPoints = 20, RatingCount = 4 },
            new() { Id = 5, Title = "Guacamole", Category = "Snacks",
                Ingredients = "3 ripe avocados\n1 lime, juiced\n½ tsp salt\n½ cup diced onion\n3 tbsp fresh cilantro\n2 roma tomatoes, diced\n1 tsp minced garlic\n1 pinch cayenne pepper",
                Steps = "1. Halve avocados, remove pit, and scoop into a bowl.\n2. Mash with a fork to desired consistency.\n3. Stir in lime juice and salt.\n4. Mix in onion, cilantro, tomatoes, and garlic.\n5. Add cayenne pepper.\n6. Refrigerate for 1 hour before serving with tortilla chips.",
                TotalRatingPoints = 9, RatingCount = 2 },
            new() { Id = 6, Title = "Iced Matcha Latte", Category = "Beverages",
                Ingredients = "2 tsp matcha powder\n2 tbsp hot water\n1 cup milk of choice\nIce\n1 tsp honey (optional)",
                Steps = "1. Sift matcha powder into a bowl.\n2. Add hot water and whisk until smooth and frothy.\n3. Fill a glass with ice.\n4. Pour milk over ice.\n5. Pour matcha over milk.\n6. Stir and sweeten with honey if desired.",
                TotalRatingPoints = 8, RatingCount = 2 },
        ];
        _nextId = 7;
    }

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }

    public Recipe Add(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

