arguments.file_text:
@page "/recipes"
@page "/recipes/{Category}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(Category is not null ? $"{Category} Recipes" : "All Recipes") — RecipeShare</PageTitle>

<h1>@(Category is not null ? $"{Category} Recipes" : "All Recipes")</h1>

@if (Category is not null)
{
    <a href="/recipes" class="btn btn-sm btn-outline-secondary mb-3">← All Categories</a>
}

@if (_recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category yet.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <span class="badge bg-secondary">@recipe.Category</span>
                        @if (recipe.RatingCount > 0)
                        {
                            <span class="ms-2 text-warning">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    @(i <= Math.Round(recipe.AverageRating) ? "★" : "☆")
                                }
                            </span>
                            <small class="text-muted">(@recipe.RatingCount)</small>
                        }
                        <a href="@($"/recipe/{recipe.Id}")" class="btn btn-primary btn-sm mt-2 d-block">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string? Category { get; set; }

    private IReadOnlyList<RecipeShare.Models.Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = Category is not null
            ? RecipeService.GetByCategory(Category)
            : RecipeService.GetAll();
    }
}

@page "/recipe/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe Not Found") — RecipeShare</PageTitle>

@if (_recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/recipes">← Back to recipes</a>
}
else
{
    <a href="@($"/recipes/{_recipe.Category.ToLowerInvariant()}")" class="btn btn-sm btn-outline-secondary mb-3">
        ← Back to @_recipe.Category
    </a>

    <h1>@_recipe.Title</h1>
    <span class="badge bg-secondary fs-6">@_recipe.Category</span>

    <StarRating RecipeId="@_recipe.Id" @rendermode="InteractiveServer" />

    <h3 class="mt-4">🧾 Ingredients</h3>
    <ul class="list-group list-group-flush mb-4">
        @foreach (var line in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li class="list-group-item">@line</li>
        }
    </ul>

    <h3>📝 Steps</h3>
    <ol class="list-group list-group-numbered list-group-flush">
        @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && text[0] is >= '0' and <= '9' && text.Contains('.'))
            {
                text = text[(text.IndexOf('.') + 1)..].TrimStart();
            }
            <li class="list-group-item">@text</li>
        }
    </ol>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeShare.Models.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@inject RecipeShare.Services.RecipeService RecipeService

<div class="my-3 p-3 border rounded bg-light">
    <strong>Rate this recipe:</strong>
    <span class="ms-2 fs-4" style="cursor: pointer;">
