+        {
+            <li class="list-group-item">@line</li>
+        }
+    </ul>
+
+    <h3>📝 Steps</h3>
+    <ol class="list-group list-group-numbered list-group-flush">
+        @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
+        {
+            var text = step.TrimStart();
+            if (text.Length > 2 && text[0] is >= '0' and <= '9' && text.Contains('.'))
+            {
+                text = text[(text.IndexOf('.') + 1)..].TrimStart();
+            }
+            <li class="list-group-item">@text</li>
+        }
+    </ol>
+}
+
+@code {
+    [Parameter] public int Id { get; set; }
+
+    private RecipeShare.Models.Recipe? _recipe;
+
+    protected override void OnParametersSet()
+    {
+        _recipe = RecipeService.GetById(Id);
+    }
+}
