@inject RecipeShare.Services.RecipeService RecipeService

<div class="my-3 p-3 border rounded bg-light">
    <strong>Rate this recipe:</strong>
    <span class="ms-2 fs-4" style="cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => Rate(star)"
                  @onmouseover="() => _hover = star"
                  @onmouseout="() => _hover = 0"
                  class="@(i <= DisplayStars ? "text-warning" : "text-muted")">★</span>
        }
    </span>

    @if (_submitted)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }

    @{ var recipe = RecipeService.GetById(RecipeId); }
    @if (recipe is not null && recipe.RatingCount > 0)
    {
        <small class="ms-3 text-muted">
            Avg: @recipe.AverageRating.ToString("F1") / 5
            (@recipe.RatingCount @(recipe.RatingCount == 1 ? "rating" : "ratings"))
        </small>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _hover;
    private int _selected;
    private bool _submitted;

    private int DisplayStars => _hover > 0 ? _hover : _selected;

    private void Rate(int stars)
    {
        _selected = stars;
        RecipeService.AddRating(RecipeId, stars);
        _submitted = true;
    }
}

